begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "8fa2f695-21c5-5caa-9894-92d76aabd4b2", "feature_slug": "cs-phone-number-purchasing", "title": "Edge Functions", "content": "### `cs-phone-numbers` (v2, JWT-protected)\n\nProvider-abstracted phone number management. Adapter pattern with `PhoneNumberProvider` interface.\n\n**Actions:**\n\n| Action | Payload | What it does |\n|---|---|---|\n| `search` | `{provider, country_code, area_code?, contains?, capabilities?, limit?}` | Search available numbers via provider API. Returns normalized list with pricing. |\n| `purchase` | `{provider, phone_number, friendly_name?, country_code?, channel_use?}` | Purchase number, auto-configure webhooks, save to `cs_phone_numbers`. |\n| `configure` | `{provider, provider_sid, voice_enabled?, sms_enabled?, channel_use?}` | Update webhooks on existing number. |\n| `release` | `{provider, phone_id}` | Release number back to provider, mark as released in DB. |\n| `provision-subaccount` | `{provider, friendly_name?}` | (Master mode) Create provider subaccount for merchant. Requires `TWILIO_MASTER_ACCOUNT_SID` + `TWILIO_MASTER_AUTH_TOKEN` env secrets. Saves subaccount creds to `merchant_credentials`. |\n\n**TwilioAdapter → Twilio API mapping:**\n\n| Method | Twilio API |\n|---|---|\n| `searchAvailable` | `GET /2010-04-01/Accounts/{sid}/AvailablePhoneNumbers/{country}/Local.json` |\n| `purchase` | `POST /2010-04-01/Accounts/{sid}/IncomingPhoneNumbers.json` |\n| `configureWebhooks` | `POST /2010-04-01/Accounts/{sid}/IncomingPhoneNumbers/{pnSid}.json` |\n| `release` | `DELETE /2010-04-01/Accounts/{sid}/IncomingPhoneNumbers/{pnSid}.json` |\n| `provisionSubaccount` | `POST /2010-04-01/Accounts.json` (creates subaccount under master) |\n\n### `webhook-twilio-sms` (no JWT — called by Twilio)\n\nInbound SMS webhook. Twilio sends POST with form-encoded `From`, `To`, `Body`, `MessageSid`.\n\n1. Resolve merchant by looking up `To` number in `cs_phone_numbers`\n2. Validate Twilio HMAC-SHA1 signature against `auth_token`\n3. Call `cs_api_receive_message(platform_type=''sms'', platform_user_id=From)`\n4. Emit Inngest `cs/message.received` event\n5. Return empty TwiML `<Response/>` (replies go async via messaging-service)\n\n### `webhook-twilio-voice` (no JWT — called by Twilio)\n\nInbound voice webhook. Twilio sends POST with form-encoded `From`, `To`, `CallSid`, `CallStatus`.\n\n1. Resolve merchant by looking up `To` number in `cs_phone_numbers` (filtered by `channel_use @> ''{voice}''`)\n2. Resolve contact via `cs_fn_resolve_contact(platform_type=''voice'', platform_user_id=From)`\n3. Emit Inngest `cs/voice.call_started` event\n4. Look up ElevenLabs agent_id from `merchant_credentials` (service_name=''elevenlabs'')\n5. Return TwiML with `<Connect><Stream url=\"wss://api.elevenlabs.io/v1/convai/conversation?agent_id=...\"/>` to connect to ElevenLabs\n6. If no voice agent configured, returns `<Say>` with Thai message + `<Hangup/>`\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Phone_Number_Purchasing.md#L136 Edge Functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-phone-number-purchasing", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "2410a96557c7fa89cb495be8717e5c5695ac0d2bd2571408bb95a7cb8aac4344", "truncated": false}, "is_active": true}, {"id": "4aaf344a-55d1-55f9-a054-dc707f7263d6", "feature_slug": "cs-phone-number-purchasing", "title": "Table: `cs_phone_numbers`", "content": "Provider-agnostic phone number inventory. One row per purchased number.\n\n| Column | Type | Default | Notes |\n|---|---|---|---|\n| `id` | uuid PK | `gen_random_uuid()` | |\n| `merchant_id` | uuid NOT NULL | — | FK → merchant_master. RLS scoped. |\n| `credential_id` | uuid NOT NULL | — | FK → merchant_credentials. Which provider account owns this. |\n| `provider` | text NOT NULL | `''twilio''` | `twilio`, future: `vonage`, `telnyx` |\n| `phone_number` | text NOT NULL | — | E.164 format (+66812345678) |\n| `friendly_name` | text | — | Merchant-assigned label |\n| `country_code` | text NOT NULL | — | ISO 3166-1 alpha-2 (TH, US, SG) |\n| `capabilities` | text[] NOT NULL | `''{voice,sms}''` | What the number supports from provider |\n| `provider_sid` | text NOT NULL | — | Provider''s ID for this number (Twilio: PNxxxx) |\n| `status` | text NOT NULL | `''active''` | `active` / `released` / `suspended` |\n| `channel_use` | text[] NOT NULL | `''{voice,sms}''` | What this number is configured for in our system |\n| `monthly_cost_cents` | integer | `0` | USD cents |\n| `voice_webhook_configured` | boolean NOT NULL | `false` | Whether voice webhook points to us |\n| `sms_webhook_configured` | boolean NOT NULL | `false` | Whether SMS webhook points to us |\n| `purchased_at` | timestamptz NOT NULL | `now()` | |\n| `released_at` | timestamptz | — | Set when released |\n| `created_at` | timestamptz NOT NULL | `now()` | |\n| `updated_at` | timestamptz NOT NULL | `now()` | `trigger_set_updated_at` |\n\n**Indexes:**\n- `(phone_number)` — unique\n- `(provider, provider_sid)` — unique\n- `(merchant_id)` — for list queries\n\n**RLS:** `merchant_id = get_current_merchant_id()`\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Phone_Number_Purchasing.md#L61 Table: `cs_phone_numbers`", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-phone-number-purchasing", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c1d94a825d659604b96c2c99f6d160a22bac023d98865599cbc8df58182dabfa", "truncated": false}, "is_active": true}, {"id": "432b2ece-d679-5e63-b4d8-7b7796b660ea", "feature_slug": "cs-phone-number-purchasing", "title": "Architecture", "content": "```\nPHONE NUMBER PURCHASE FLOW:\n  Admin UI → cs-phone-numbers Edge Function (adapter pattern)\n    → TwilioAdapter.searchAvailable() → Twilio REST API\n    → TwilioAdapter.purchase() → Twilio REST API\n    → cs_fn_upsert_phone_number → cs_phone_numbers table\n    → Auto-configures voice + SMS webhooks on purchased number\n\nINBOUND SMS:\n  SMS sender → Twilio number → webhook-twilio-sms Edge Function\n    → Resolve merchant by To number (cs_phone_numbers lookup)\n    → Validate Twilio HMAC signature\n    → cs_api_receive_message(platform_type=''sms'')\n    → Emit Inngest cs/message.received → AI pipeline\n    → Return empty TwiML (reply async via messaging-service)\n\nINBOUND VOICE:\n  Caller → Twilio number → webhook-twilio-voice Edge Function\n    → Resolve merchant by To number (cs_phone_numbers lookup)\n    → cs_fn_resolve_contact(platform_type=''voice'')\n    → Emit Inngest cs/voice.call_started\n    → Return TwiML: <Connect><Stream> to ElevenLabs WebSocket\n    → ElevenLabs STT/TTS → voice-custom-llm Edge Function (existing)\n\nOUTBOUND SMS (pending — messaging-service adapter):\n  Agent/AI reply → messaging-service (Render)\n    → twilio_sms adapter → Twilio Messages API\n    → Delivery status callback\n\nMASTER SUBACCOUNT PROVISIONING:\n  Admin UI → cs-phone-numbers Edge Function (action: provision-subaccount)\n    → Read TWILIO_MASTER_ACCOUNT_SID/AUTH_TOKEN from env secrets\n    → TwilioAdapter.provisionSubaccount() → Twilio Accounts API\n    → Save subaccount credentials to merchant_credentials\n    → All subsequent operations use subaccount credentials\n```\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/CS_Phone_Number_Purchasing.md#L20 Architecture", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "cs-phone-number-purchasing", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "3b7d0a49ef1591225025c4ead4be1a6f084f0b5b26e9881764e810510bb42e2f", "truncated": false}, "is_active": true}, {"id": "026d8075-8c42-56ae-bd91-1cc14d956a79", "feature_slug": "cs-phone-number-purchasing", "title": "Integration Hub Entry", "content": "Added to `integration_type_master`:\n\n| Field | Value |\n|---|---|\n| `platform_key` | `twilio` |\n| `platform_name` | `Twilio` |\n| `integration_key` | `twilio` |\n| `platform_order` | `6` |\n\nField definitions in `integration_field_definitions`:\n\n| Field | Group | Type | Input | Required | Sensitive |\n|---|---|---|---|---|---|\n| `account_sid` | Account Credentials | string | normal | yes | yes |\n| `auth_token` | Account Credentials | string | password | yes | yes |\n| `account_mode` | Settings | string | select (byot/master) | yes | no |\n\nCredentials saved to `merchant_credentials` with `service_name = ''twilio''` via existing `bff_upsert_integration_config(''twilio'', {...})`.\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/CS_Phone_Number_Purchasing.md#L95 Integration Hub Entry", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "cs-phone-number-purchasing", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "01e998b3358732d83f741bfd828250305cf6e6582aa55cbd58645ca8643b6420", "truncated": false}, "is_active": true}, {"id": "8840c061-82ed-525a-b603-a2977eb89959", "feature_slug": "cs-phone-number-purchasing", "title": "CS Phone Number Purchasing Domain Reference", "content": "**Keywords:** twilio, phone_number, purchase_number, sms, voice, provider, adapter, subaccount, byot, master, cs_phone_numbers, webhook_twilio_sms, webhook_twilio_voice\n**Source:** `CS_Phone_Number_Purchasing.md`\n**Tables:** `cs_phone_numbers`\n| Function | Type | Purpose |\n|---|---|---|\n| `cs_bff_get_phone_numbers` | BFF | List active numbers (provider-agnostic) |\n| `cs_bff_get_phone_number_details` | BFF | Single number + 30-day stats |\n| `cs_fn_upsert_phone_number` | Backend | Insert/update after provider purchase |\n| `cs_fn_release_phone_number` | Backend | Mark released |", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-phone-number-purchasing.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-phone-number-purchasing", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "35492fb998cfc7861fb3ec81d2b788a3d8245bac823e37d2569484316dc85979", "truncated": false}, "is_active": true}, {"id": "a50a91ed-e4b4-5a42-a87e-0eb5d6b25cde", "feature_slug": "cs-platform-features-feature-spec", "title": "CS Platform Features (Feature Spec) Domain Reference", "content": "**Keywords:** testing, simulation, a_b_experiment, notifications, time_tracking, self_service, customer_portal, web_form, knowledge_base_public, administration, multi_tenancy, security, pdpa, broadcast, outbound_voice, event_triggered\n**Source:** `CS_Platform_Features.md`", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-platform-features-feature-spec.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-platform-features-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "621a684cbb6c89103c4ff7b00e4c61abd6d0cd8254443e1fb53972f7d0e8eddc", "truncated": false}, "is_active": true}, {"id": "2c8c29f7-37e5-5bbc-aa94-e359a961286a", "feature_slug": "cs-platform-features-feature-spec", "title": "8. TESTING AND SIMULATION", "content": "### 8.1 Agent Simulator\n\n- Test the AI agent without real customers\n- Chat simulator: type messages as a mock customer, see AI responses\n- Voice simulator: test voice agent with text-to-speech simulation\n- Test specific procedures/journeys end-to-end\n- Verify action execution in sandbox mode (no real API calls)\n\n### 8.2 Automated Test Suites\n\n- Define test cases: input message, expected behavior (reply content, action taken, escalation)\n- Regression testing: run test suite before deploying changes\n- Auto-generated tests: AI creates test cases from existing procedures and knowledge base (like Sierra)\n- Coverage report: which intents/procedures have tests, which don''t\n\n### 8.3 A/B Experimentation\n\n- Run two versions of a procedure simultaneously\n- Split traffic by percentage (e.g., 80% current, 20% new)\n- Measure: resolution rate, CSAT, escalation rate, average handle time\n- Statistical significance calculation\n- One-click promote winner\n\n---", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["technical", "testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/CS_Platform_Features.md#L5 8. TESTING AND SIMULATION", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "overview", "feature_slug": "cs-platform-features-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "107954a434b8d6c1c1a9d03d29056a7342478b497ef04070865b68b7a8329ed0", "truncated": false}, "is_active": true}, {"id": "7d29c9c4-259f-53e6-bff3-4334e09558a6", "feature_slug": "cs-procedures-aops", "title": "Functions — Deployed", "content": "### Pipeline\n\n| Function | Type | Signature | Purpose |\n|---|---|---|---|\n| `cs_fn_get_active_procedure` | Backend | `(p_merchant_id, p_intent)` | Lookup active procedure for merchant + intent. Returns full procedure jsonb (raw_content, compiled_steps, config, guardrails). |\n| `cs_fn_save_procedure_state` | Backend | `(p_conversation_id, p_procedure_id, p_procedure_state)` | Save AOP execution state to cs_conversations.procedure_state between Inngest steps. |\n\n### Admin BFF\n\n| Function | Type | Signature | Purpose |\n|---|---|---|---|\n| `cs_bff_upsert_procedure` | BFF | `(p_procedure_id, p_name, p_description, p_trigger_intent, p_flexibility, p_raw_content, p_compiled_steps, p_config, p_guardrails)` | Create: inserts new row, validates trigger_intent uniqueness. Update: inserts new version row, deactivates old. |\n| `cs_bff_activate_procedure` | BFF | `(p_procedure_id, p_is_active)` | Toggle is_active. On activate: deactivates other versions with same trigger_intent. |\n\n### Direct CRUD (Supabase client + RLS)\n\n- List procedures: direct table read", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Procedures.md#L323 Functions — Deployed", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-procedures-aops", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "9d688b0dd9016fbc47d9756af4021761f3b47a7f74606e9e8576086ed62b8b19", "truncated": false}, "is_active": true}, {"id": "d0f1fff7-e407-5913-882a-e1ea5a64c1cd", "feature_slug": "cs-procedures-aops", "title": "Core Tables", "content": "### cs_procedures\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `merchant_id` | uuid FK | |\n| `name` | text | \"Refund Request Handler\" |\n| `description` | text | |\n| `trigger_intent` | text | `refund_request`, `order_tracking`, `product_inquiry`, `complaint` |\n| `flexibility` | text | `strict`, `guided`, `agentic` |\n| `raw_content` | text | Natural language AOP (what the LLM reads at runtime) |\n| `compiled_steps` | jsonb | Parsed: step list, tool refs, branch map, code conditions, data flow |\n| `config` | jsonb | Per-procedure overrides: `{tone_override, max_turns, timeout}` |\n| `is_active` | boolean | |\n| `version` | int | Increment on edit |\n| `created_by` | uuid | |\n| `created_at` | timestamptz | |\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Procedures.md#L8 Core Tables", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-procedures-aops", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "4f918c6179a972dd1283a9188dc5fdad4e6002820e9d5875a13d8cf9a9062c76", "truncated": false}, "is_active": true}, {"id": "49a9e211-5b02-595b-be66-58f353969ecc", "feature_slug": "cs-procedures-aops", "title": "CS Procedures (AOPs) Domain Reference", "content": "**Keywords:** procedure, aop, agent_operating_procedure, intent, trigger_intent, flexibility, strict, guided, agentic, compiled_steps, raw_content, tone_override, cs_procedures, step, tool_reference, data_needs, action_tools, entity_extractors, step_topic, required_variables, prefetch, graph_executor, deterministic_prefetch, code_conditions, variables_in, variables_out, query_hints, args_from\n**Source:** `CS_Procedures.md`\n**Tables:** `cs_procedures`, `cs_action_config`, `workflow_action_type_config` (domain=''cs'')\n| Function | Type | Purpose |\n|---|---|---|\n| `cs_bff_get_procedures` | BFF | List procedures for a merchant |\n| `cs_bff_upsert_procedure` | BFF | Create or update procedure (auto-compiles, auto-versions) |\n| `cs_fn_get_active_procedure` | Backend | Get active procedure for merchant + intent |\n| `cs_fn_compile_procedure` | Backend | Enriches compiled_steps with data_needs (args_from mapping), action_tools (requires_confirmation), entity_extractors (order_number regex, platform/product keywords). Resolves tool_type from cs_action_config → falls back to workflow_action_type_config. |\n| `cs_fn_seed_action_config` | Backend | Seeds cs_action_config for a merchant from workflow_action_type_config registry. Called on CS activation or platform connection. |\n|---|---|---|\n| `lookup_order` | data | Fetch order by number + platform from marketplace API |\n| `get_recent_orders` | data | Fetch recent orders for contact (optional platform filter) |\n| `check_product_stock` | data | Check product availability on platform |\n| `get_product_price` | data | Get current price on platform |\n| `get_customer_profile` | data | Fetch CRM loyalty data via bridge |\n| `search_products` | data | Search product catalog by keyword/category/filters on platform |\n| `check_promotion` | data | Check active promotions/coupons on platform, or validate a specific promo code |\n| `get_order_shipping` | data | Get shipping address, tracking info, carrier details for an order |\n| `recommend_products` | data | AI-assisted product recommendations from platform catalog (context + filters) |\n| `cancel_order` | action | Cancel order on marketplace (requires platform + order_number) |\n| `process_refund` | action | Process refund on marketplace (requires platform + order_number) |\n| `create_order` | action | Create new order on platform (phone orders, replacement orders). Requires items, shipping address, customer email |\n| `update_order` | action | Modify existing order (shipping address, notes, items) before shipment |\n| `apply_coupon` | action | Apply promo/coupon code to an existing order or give to customer |\n| `create_voucher` | action | Create loyalty or platform voucher/coupon |\n| `create_ticket` | action | Create support ticket from conversation |\n| `close_conversation` | action | Mark conversation resolved |\n| `trigger_csat_survey` | action | Send satisfaction survey |\n**Key Business Rules (summary):**\n- Flexibility spectrum: `strict` (follow exactly) → `guided` (adapt flow) → `agentic` (advisory only)\n- Versioning: new edit = new row with version+1, old row set `is_active = false`\n- Only one active version per `trigger_intent` per merchant\n- `@ToolName` references in `raw_content` validated against `cs_action_config` for the merchant\n- `compiled_steps` contains enhanced graph structure: per-step `data_needs` (source + args_from + when), `action_tools` (tool + args_from + requires_confirmation), `entity_extractors` (regex for order_number, keyword for platform/product), `step_topic`, `required_variables`\n- `platform` is a first-class variable: extracted from customer message via keyword extractor, collected by AI if not mentioned, required by all marketplace data/action tools\n- Conversation channel ≠ order platform (customer on LINE may ask about Shopee order)\n- Graph executor reads `data_needs` and calls data tools directly as code — LLM never makes data tool calls\n- 3-tier prefetch: Tier 1 (data tools in data_needs), Tier 2 (knowledge/conversation only), Tier 3 (no AOP, explorer fallback)\n- Per-merchant action overrides in `cs_action_config`: action_constraints (max_amount, blocked_statuses, requires_confirmation), seeded from registry via `cs_fn_seed_action_config`", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-procedures-aops.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-procedures-aops", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "105ea687ec7fe66af9d416c16cc4b9439d63499aa224ce1795fcd32b2416a023", "truncated": false}, "is_active": true}, {"id": "a1c1575b-4b32-521f-a52e-ff9ba61ec4fb", "feature_slug": "cs-rules-engine-feature-spec", "title": "4. RULES ENGINE (Deterministic Automation)", "content": "*Note: Section numbers shifted — SLA Management is now section 3, Rules Engine is section 4, AI Agent is section 5, Actions is section 6, etc.*\n\n### 3.1 Triggers\n\nTriggers fire automation based on events:\n- New conversation created\n- New message received\n- Conversation assigned / unassigned\n- Conversation status changed (opened, resolved, etc.)\n- SLA breach approaching (e.g., 10 min before deadline)\n- SLA breached\n- Customer identified (loyalty data loaded)\n- Specific keyword detected\n- Specific intent detected (AI classification)\n- Specific sentiment detected (negative, angry)\n- Time-based: X hours since last response\n- Platform-specific: order status changed, return requested\n\n### 3.2 Conditions\n\nConditions filter when the rule applies:\n- Channel is / is not (Shopee, LINE, voice, email, etc.)\n- Brand / store is\n- Customer tag is / has\n- Customer tier is (VIP, Gold, etc.)\n- Conversation tag contains\n- Message contains keyword / phrase\n- AI intent is (refund, tracking, complaint, pre-sale, etc.)\n- AI sentiment is (positive, neutral, negative, angry)\n- Language is (Thai, English, etc.)\n- Business hours: during / outside\n- Agent assigned: yes / no\n- Conversation count for this customer: first time / returning\n- Order exists: yes / no\n- Order status is (pending, shipped, delivered, cancelled)\n\n### 3.3 Actions\n\nWhat the rule executes:\n- Send auto-reply (text, template with variables)\n- Assign to agent / team / AI agent\n- Add tag / remove tag\n- Set priority\n- Set status (pending, snoozed)\n- Send internal note\n- Trigger webhook (notify external system)\n- Create ticket in external system\n- Escalate to supervisor\n- Send CSAT survey\n- Close conversation\n- Send notification to Slack/Teams/LINE Notify\n- Execute API action (cancel order, create voucher, etc.)\n\n### 3.4 Rule Management\n\n- Visual rule builder (no-code)\n- Rule ordering / priority (first match wins, or execute all matching)\n- Rule enable/disable toggle\n- Rule activity log: see how many times each rule fired\n- Rule testing: simulate with sample conversation\n- Rule templates: pre-built rules for common scenarios (e.g., \"Auto-close after customer confirms resolution\")\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/CS_Rules_Engine.md#L5 4. RULES ENGINE (Deterministic Automation)", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "cs-rules-engine-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c9aab8bd0a36183973d71e0d47fb51d5598d84da92015f476ddab7065869621c", "truncated": false}, "is_active": true}, {"id": "1be58615-c8f9-5bb1-b9d4-80b4a14e0d23", "feature_slug": "cs-rules-engine-feature-spec", "title": "CS Rules Engine (Feature Spec) Domain Reference", "content": "**Keywords:** rules, trigger, condition, action, auto_reply, auto_assign, auto_tag, auto_escalate, keyword_detection, intent_detection, sentiment_detection, rule_builder\n**Source:** `CS_Rules_Engine.md`", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-rules-engine-feature-spec.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-rules-engine-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "9083bf7dc506abeab52eda968f0b47d68a549d9969a0e3dc953468849e5af140", "truncated": false}, "is_active": true}, {"id": "2fe7cf25-fede-5ba8-98df-0665adcaa4bb", "feature_slug": "cs-sla-management-feature-spec", "title": "3. SLA MANAGEMENT", "content": "### 3.1 SLA Policies\n\n- Define SLA policies with target response time and target resolution time\n- Multiple SLA policies per brand (e.g., VIP customers get 1-hour response, standard customers get 4-hour)\n- SLA assignment rules: automatically apply the right SLA based on customer tier, channel, priority, conversation topic, or custom field\n- SLA applies only during business hours (not counting nights/weekends/holidays)\n- SLA pause: timer pauses when conversation is in \"waiting on customer\" or \"snoozed\" status\n\n**SLA consequences on execution (SLAs determine WHEN to act, not WHAT to do):**\n\n| SLA Event | Automated Consequence |\n|---|---|\n| Approaching deadline (e.g., 10 min before) | Notify assigned agent, bump priority to urgent, highlight in queue |\n| Deadline breached | Escalate to supervisor, auto-reassign to available agent, alert via Slack/LINE Notify |\n| Timer paused | Status = \"waiting on customer\" or \"snoozed\" → timer stops, resumes when customer replies |\n| Different SLA per tier | VIP → 1-hour response. Standard → 4-hour. AI can be instructed to prioritize accordingly |\n\nSLAs create urgency and routing changes. They do NOT change the resolution logic (the AOP handles what to do; the SLA handles how fast to do it).\n\n### 3.2 Business Hours\n\n- Define business hours per brand (e.g., Mon-Fri 9am-6pm Bangkok time)\n- Multiple schedules: different hours for different teams, channels, or customer tiers (e.g., VIP support is 24/7, standard is business hours only)\n- Holiday calendar: define holidays per country/brand — SLA timers pause on holidays\n- Timezone support: each schedule has its own timezone; agents and customers can be in different zones\n- After-hours behavior: configure what happens outside business hours (AI agent takes over, auto-reply with expected response time, route to different team in another timezone)\n\n### 3.3 SLA Reporting\n\n- SLA compliance rate: % of conversations that met response and resolution targets\n- SLA breach report: which conversations breached, by how much, who was assigned\n- SLA trend: compliance over time (improving or degrading)\n- Per-agent SLA performance\n- Per-channel SLA performance\n- SLA by customer tier: are VIP SLAs being met?\n\n---", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/CS_SLA.md#L5 3. SLA MANAGEMENT", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "overview", "feature_slug": "cs-sla-management-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "9d90056319485ee4bfd06801707951e05a46926abb28fb28f185c550bbb2b1d1", "truncated": false}, "is_active": true}, {"id": "20e71af4-2436-5dbf-aeb5-39342c7ffeb3", "feature_slug": "cs-sla-management-feature-spec", "title": "CS SLA Management (Feature Spec) Domain Reference", "content": "**Keywords:** sla, response_time, resolution_time, business_hours, holiday, breach, escalation, sla_policy, timer, pause\n**Source:** `CS_SLA.md`", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-sla-management-feature-spec.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-sla-management-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "1ca2d6d8967270071e950e725a5a12c633c43b9123ca9aedd8b09e53f0c0595b", "truncated": false}, "is_active": true}, {"id": "6ab582aa-942b-54f1-813c-ac65f15bf041", "feature_slug": "cs-teams-agent-profiles", "title": "DATABASE SCHEMA DESIGN — CS Module", "content": "This section covers the conceptual model, naming conventions, and table schemas for the CS module. These are decisions that affect every feature built on top.\n\n---\n\n### 1. Conceptual Framework\n\n#### 1.1 The CS AI is a Composition, Not an Agent\n\nThe CRM''s marketing AI (`amp_agent`) is an **autonomous decision-maker** — it has objectives (drive_purchase), KPIs, deliberation cycles, and chooses actions independently. It IS an agent.\n\nThe CS AI is fundamentally different. It is an **orchestrated composition** of independent components:\n\n```\nCS AI behavior at runtime =\n    Brand config (voice, tone, language, model)        — from cs_brand_config\n  + Guardrails (topic rules, escalation triggers)      — from cs_brand_config + procedure + action config\n  + Knowledge (articles, embeddings)                   — from cs_knowledge_articles\n  + Procedure (step-by-step AOP for this intent)       — from cs_procedures\n  + Available tools (with per-tool constraints)         — from cs_brand_config.action_config\n  + Customer memory (cross-session facts)              — from cs_customer_memory\n  + Conversation context (messages, history)            — from cs_conversations + cs_messages\n```\n\nNo single \"agent\" entity owns all of this. The components are independent, each with their own lifecycle and table. They converge on the **conversation** at runtime.\n\n**Why this matters for schema design**: There is no `cs_agent` table. The AI behavior emerges from composing components, not from configuring a standalone entity.\n\n#### 1.1b Multi-Model Pipeline (\"Sub-Agents\") — Infrastructure, Not Entities\n\nSierra, Decagon, and (to a lesser degree) Intercom all describe \"sub-agents\" or \"specialized models.\" This is often misunderstood as separate configurable agents per topic. It is not. It is **multi-model orchestration within a single processing pipeline** — different models handling different computational tasks per request.\n\n**Sierra''s \"constellation of models\"** (15+ models per agent):\n\n| Pipeline stage | Specialized for | Model type |\n|---|---|---|\n| Intent/classification | Fast, high-precision categorization | Small fine-tuned model |\n| Tool calling | Low-latency API decisions (orders, inventory) | Fast model with tight latency constraints |\n| Long-context reasoning | Complex policies, dense info, multi-step logic | Large frontier model (high reasoning) |\n| Tone/voice generation | On-brand, warm, conversational output | Fine-tuned or prompted for brand voice |\n| Supervisor (\"Jiminy Cricket\") | Validates actions, enforces guardrails, catches errors | Separate model with independent evaluation |\n\n**Decagon''s \"specialized model network\"** (80%+ proprietary models):\n\n| Pipeline stage | Specialized for | Training method |\n|---|---|---|\n| Intent classifier | What does the customer want? | Fine-tuned (SFT + RL) |\n| Workflow executor | Follow AOP steps, generate response | Fine-tuned on conversation data |\n| Hallucination detector | Check response before sending | Fine-tuned classifier |\n| Bad actor detector | Screen for manipulation, adversarial prompts | Fine-tuned at conversation start |\n| Escalation decider | Should this go to a human? | Fine-tuned on escalation patterns |\n\n**Intercom Fin**: Single-agent system. No multi-model orchestration. Simpler but less optimizable.\n\n**Key distinction**: These \"sub-agents\" are invisible to the CX team. They don''t configure them. They don''t create them. They''re infrastructure that the platform manages. The CX team configures ONE thing per brand (voice, guardrails, knowledge, procedures) and the platform decides which model handles which stage.\n\n**How this maps to our architecture — the processing pipeline:**\n\n```\nMessage arrives\n    → [Stage 1: Bad Actor Screening]     — fast classifier, runs in parallel\n    → [Stage 2: Intent Classification]   — fast model (GPT-4o-mini or fine-tuned)\n    → [Stage 3: Knowledge Retrieval]     — embedding model + pgvector similarity search\n    → [Stage 4: Main Reasoning]          — powerful model (GPT-4o / Claude), follows procedure\n    → [Stage 5: Response Generation]     — same model or tone-specific model\n    → [Stage 6: Hallucination Check]     — separate model validates factual accuracy\n    → [Stage 7: Supervisor Verification] — for high-risk actions only (refunds, cancellations)\n    → Send response\n```\n\n**Where this lives in the schema**: Not in separate tables — in `cs_brand_config.model_config`:\n\n```json\n{\n  \"intent_model\": {\"provider\": \"openai\", \"model\": \"gpt-4o-mini\"},\n  \"reasoning_model\": {\"provider\": \"anthropic\", \"model\": \"claude-sonnet-4\"},\n  \"embedding_model\": {\"provider\": \"openai\", \"model\": \"text-embedding-3-small\"},\n  \"verification_model\": {\"provider\": \"openai\", \"model\": \"gpt-4o-mini\"},\n  \"hallucination_check_enabled\": true,\n  \"bad_actor_screening_enabled\": true,\n  \"supervisor_verification\": {\n    \"enabled\": true,\n    \"for_action_types\": [\"process_refund\", \"cancel_order\", \"account_change\"]\n  }\n}\n```\n\nNo new tables for the multi-model pipeline. It''s an execution concern handled in the AI service code (Render). The database stores which models and which stages are enabled.\n\n#### 1.1c Our Approach: Context Injection on General LLMs (Not Specialized Models)\n\nSierra and Decagon achieve precision by **fine-tuning small specialized models** — one for intent classification, one for hallucination detection, one for escalation, etc. Each model is trained on millions of real conversations using supervised fine-tuning (SFT) and reinforcement learning (RL). The result: each model is an expert at its one job, fast, cheap per call, and highly accurate.\n\nWe cannot start there. Fine-tuning requires:\n- Millions of labeled conversations (we have zero at launch)\n- ML engineering team to train, evaluate, and maintain each model\n- Infrastructure for model serving, versioning, A/B testing models\n- Months of iteration per model\n\n**Our approach: one general-purpose LLM + context injection.** Instead of training a specialized model for each task, we inject the right context into one powerful model''s prompt and let it handle everything.\n\n**How it works — same pipeline stages, different execution:**\n\n| Pipeline stage | Sierra/Decagon approach | Our approach (Phase 1) |\n|---|---|---|\n| **Intent classification** | Fine-tuned classifier → returns `refund_request` in ~50ms | Same LLM, first call with a classification prompt: \"Given this message, classify the intent.\" ~200ms. Or use a structured output schema. |\n| **Knowledge retrieval** | Proprietary RAG with fine-tuned reranker | pgvector semantic search + OpenAI embeddings. Standard RAG. Same architecture, off-the-shelf models. |\n| **Main reasoning** | Fine-tuned model trained on successful resolutions | General frontier model (GPT-4o / Claude) with full context injected: brand config + procedure + knowledge chunks + customer memory + guardrails. The prompt IS the specialization. |\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Feature_Spec.md#L2 DATABASE SCHEMA DESIGN — CS Module", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-teams-agent-profiles", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ce85245d2d366686561d98b2e92adc6bb3271e7eb2d297c5050ed6d709f6709d", "truncated": true}, "is_active": true}, {"id": "b1c71a18-be2d-5881-8bd2-611c9a1c8445", "feature_slug": "cs-teams-agent-profiles", "title": "CS Teams & Agent Profiles Domain Reference", "content": "**Keywords:** team, agent, agent_profile, online, away, offline, max_concurrent, skills, routing, round_robin, least_busy, cs_teams, cs_agent_profiles\n**Source:** `CS_Feature_Spec.md` (sections 4.8, 4.9)\n**Tables:** `cs_agent_profiles`, `cs_teams`\n| Function | Type | Purpose |\n|---|---|---|\n| `cs_bff_get_teams` | BFF | List teams for a merchant |\n| `cs_bff_upsert_team` | BFF | Create or update team |\n| `cs_bff_get_agent_profiles` | BFF | List agent profiles with online status |\n| `cs_fn_update_agent_status` | Backend | Update agent online/away/offline status |\n| `cs_fn_route_conversation` | Backend | Route conversation to best available agent |\n**Key Business Rules (summary):**\n- Agent profiles auto-provisioned on first CS inbox access\n- Identity from `admin_users` via JOIN; `cs_agent_profiles` only stores operational state\n- Teams reference `admin_users.id` in `member_admin_user_ids` array\n- Routing methods: round-robin, least-busy, manual, skill-based", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-teams-agent-profiles.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-teams-agent-profiles", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "478465e8650428e8964046134e29dc90e7c1874bf0244c8a568e07f2af4f5950", "truncated": false}, "is_active": true}, {"id": "88a67cdf-4579-5e84-8695-bffe776013d4", "feature_slug": "cs-unified-inbox-feature-spec", "title": "2. UNIFIED INBOX", "content": "### 2.0 Conversations vs Tickets — Two Distinct Concepts\n\nThe system has two core objects that work together but have different purposes and lifecycles:\n\n**Conversation** = the real-time message thread with the customer\n- Contains the actual messages (text, images, cards, voice transcripts)\n- Lives on the channel (Shopee chat, LINE, WhatsApp, email thread)\n- Can be quick and transient (\"What are your store hours?\" → answered → done)\n- One customer can have many conversations over time\n\n**Conversation Session Logic (inspired by [Freshdesk threading interval](https://support.freshdesk.com/support/solutions/articles/50000011687-understand-threading-logic)):**\n\nWhen does a new conversation start vs continuing an existing one?\n\nFor **marketplace channels** (Shopee, Lazada, TikTok Shop): follow the platform''s own threading. They provide a `conversation_id` via API — your system maps 1:1.\n\nFor **channels you control** (LINE, WhatsApp, web chat, email, voice):\n\n| Current Status | Customer Messages Again | What Happens |\n|---|---|---|\n| Resolved/Closed, within threading interval | Same conversation **reopens** |\n| Resolved/Closed, after threading interval | **New conversation** created |\n| Open/Pending, within session timeout | Message **appended** to same conversation |\n| Open/Pending, after session timeout | Old closed as \"inactive\", **new conversation** created |\n| Waiting on Customer | Always **appended** (no timeout — we''re expecting their reply) |\n\nDefault intervals (configurable per brand, per channel):\n- LINE: session_timeout = 24h, threading_interval = 48h\n- WhatsApp: session_timeout = 24h, threading_interval = 24h\n- Email: threading_interval = 72h\n- Web chat: session_timeout = 30 min\n- Voice: every call is always a new conversation\n\nWhen customer changes topic mid-conversation: AI does NOT split the conversation (that would disrupt the customer''s chat). Instead, AI creates a new **ticket** for the second issue while continuing the same conversation thread. Agent can also manually \"Split\" a message into a new ticket ([Freshdesk Split Ticket](https://support.freshdesk.com/en/support/solutions/articles/228992)).\n\n**Ticket** = a structured work item that tracks an issue to resolution\n- Created from a conversation (agent/AI clicks \"Create Ticket\") or independently (web form, email, internal)\n- Has structured fields: type, status, priority, assignee, SLA, custom fields, description\n- Has its own lifecycle: Open → In Progress → Waiting on Customer → Resolved → Closed\n- Can span multiple conversations (customer follows up days later — same ticket, new messages)\n- Can exist without a conversation (e.g., internal ticket created by supervisor)\n- Can be transferred between teams, escalated, linked to other tickets\n\n**Relationships:**\n- A conversation can exist without a ticket (simple question answered immediately — no ticket needed)\n- A ticket is always linked to at least one conversation (the originating chat)\n- One conversation can create multiple tickets (customer raises two separate issues in one chat)\n- One ticket can span multiple conversations (customer contacts again about same issue — new conversation linked to existing ticket)\n- Agents see both: the live chat (to reply) and the ticket sidebar (to track the structured work item)\n\n**When does a ticket get created?**\n- **Automatically**: when rules engine detects an issue that needs tracking (refund request, complaint, escalation)\n- **Automatically**: when AI agent determines the issue requires multi-step resolution or human involvement\n- **Manually**: agent clicks \"Create Ticket\" from a conversation\n- **From web form**: customer submits a support request via contact form → ticket created directly\n- **From email**: inbound email → ticket created automatically\n- **Internally**: supervisor creates a ticket without a customer conversation (e.g., proactive outreach task)\n\n**Ticket Lifecycle:**\n\n```\n[New] → [Open] → [In Progress] → [Waiting on Customer] → [Resolved] → [Closed]\n                       ↑                    |\n                       |                    ↓\n                       ←──── [Reopened] ←────\n```\n\n- **New**: just created, not yet assigned\n- **Open**: assigned to an agent/team, not yet worked on\n- **In Progress**: agent is actively working on it\n- **Waiting on Customer**: agent replied, waiting for customer response (SLA pauses)\n- **Resolved**: issue addressed, pending confirmation or auto-close timer\n- **Closed**: fully complete, no further action (can be reopened if customer contacts again)\n- **Reopened**: customer followed up after resolution — ticket returns to Open\n\n**Ticket Fields (structured data — like Duoke''s right sidebar):**\n- Ticket Type (dropdown: refund, complaint, product inquiry, shipping, account, etc. — configurable per brand)\n- Status (lifecycle above)\n- Priority (urgent, high, normal, low)\n- Assignee (agent or team)\n- Description (rich text: agent/AI summary of the issue)\n- SLA policy (auto-assigned based on rules)\n- Due date (derived from SLA)\n- Tags\n- Custom fields (configurable per brand — e.g., \"Order Number\", \"Product Category\", \"Refund Amount\")\n- Related customer (linked customer profile)\n- Related store/brand\n- Related order(s) (linked to marketplace orders)\n- Follow-up assignee (who should follow up after resolution)\n- Resolution category (filled on resolve: \"refunded\", \"replaced\", \"explained\", \"escalated\")\n- Root cause (filled on resolve: \"product defect\", \"shipping delay\", \"customer error\", etc.)\n\n**Agent Workspace Layout (inspired by Duoke):**\n```\n┌──────────────┬──────────────────────────┬────────────────────┐\n│              │                          │                    │\n│  Conversation│    Chat Window           │   Ticket Sidebar   │\n│  List        │                          │                    │\n│              │  [customer messages]     │  Ticket Type       │\n│  - Store A   │  [AI/agent replies]      │  Status            │\n│  - Store B   │  [system events]         │  Priority          │\n│  - Channel   │                          │  Assignee          │\n│              │                          │  Description       │\n│  Filters:    │                          │  Custom Fields     │\n│  - Unread    │                          │  Related Order     │\n│  - Assigned  │                          │  Related Customer  │\n│  - Priority  │  [reply composer]        │  SLA Timer         │\n│              │  [quick actions]         │  [Save] [Create]   │\n│              │                          │                    │\n└──────────────┴──────────────────────────┴────────────────────┘\n```\n\n**How Conversations and Tickets Flow Together:**\n\n```\nScenario 1: Simple question (no ticket needed)\n  Customer asks \"What are your store hours?\" on Shopee chat\n  → Conversation created\n  → AI answers from knowledge base\n  → Conversation resolved\n  → No ticket created\n\nScenario 2: Issue requiring tracking (ticket auto-created)\n  Customer says \"I want a refund\" on LINE\n  → Conversation created\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/CS_Unified_Inbox.md#L5 2. UNIFIED INBOX", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "overview", "feature_slug": "cs-unified-inbox-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ce773a27578419d2cf4a2c25545ab4f70197c4fcdc3d0165e8509931d386408d", "truncated": true}, "is_active": true}, {"id": "cc070dd6-5bf0-5825-93eb-aa7c2cdec409", "feature_slug": "cs-unified-inbox-feature-spec", "title": "CS Unified Inbox (Feature Spec) Domain Reference", "content": "**Keywords:** inbox, unified_inbox, conversation_view, ticket, ticket_lifecycle, views, filters, assignment, routing, round_robin, skills_based, agent_workspace, supervisor, collision_detection, canned_response, macro, snooze, merge, split, side_conversation, forward\n**Source:** `CS_Unified_Inbox.md`", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-unified-inbox-feature-spec.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-unified-inbox-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "9c95a8976696ffdc05b043dac27ee5877e00bd7763f80bacfce15997bed8cf40", "truncated": false}, "is_active": true}, {"id": "fa81897e-24a1-5656-9e2f-2bb0518f92e1", "feature_slug": "cs-voice", "title": "Key Business Rules", "content": "- One active conversation per customer per channel. Voice conversations use `modality=''voice''`.\n- Contact resolved by phone number via `cs_fn_resolve_contact(platform_type=''voice'')`.\n- Same AOP procedures execute on voice identically to chat. `flexibility` levels (strict/guided/agentic) enforced by graph executor.\n- Voice conversations appear in unified inbox alongside chat (with phone icon, duration, play button).\n- Call recordings stored externally (ElevenLabs/Twilio URL). `recording_url` in `cs_voice_calls`.\n- Post-call memory extraction uses same Inngest function as chat post-resolution.\n\n---", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/CS_Voice.md#L120 Key Business Rules", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "cs-voice", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a741a065fc8089354ae8e316126d4b8a59b40100998f74653632f090138be894", "truncated": false}, "is_active": true}, {"id": "2af0ba42-8850-5082-af1c-75fa18f1e4d6", "feature_slug": "cs-voice", "title": "POC Status", "content": "**Current:** Preview testing via ElevenLabs web widget. Full flow working: Thai STT → AOP matching → graph executor → LLM (Haiku 4.5) → Thai TTS.\n\n**Known issues:** Step advancement not working (stays on step 1), LLM latency ~2.5s (target <1.5s). See `docs/cs_voice_poc_status.md` for details.\n\n**Next:** Fix step advancement, optimize latency, set up Twilio phone number for production calls.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/CS_Voice.md#L152 POC Status", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "rules", "feature_slug": "cs-voice", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c7d94ad617de35a3c0c11086dd08eabdd8b2d5d44fbfecf95f3b18d7098a906d", "truncated": false}, "is_active": true}, {"id": "5ea0cb70-c9ea-5236-a6aa-bb4a674c34a0", "feature_slug": "cs-voice", "title": "Tables", "content": "### `cs_voice_calls` (new)\n\n| Column | Type | Notes |\n|---|---|---|\n| id | uuid PK | |\n| conversation_id | uuid FK → cs_conversations | 1:1 for voice conversations |\n| merchant_id | uuid | |\n| elevenlabs_agent_id | text | ElevenAgents agent ID |\n| elevenlabs_call_id | text | Per-call session ID |\n| phone_from | text | Caller''s phone number |\n| phone_to | text | Inbound number |\n| direction | text | `inbound` / `outbound` |\n| sip_call_id | text | Twilio Call SID |\n| call_status | text | `ringing` / `in_progress` / `completed` / `failed` / `no_answer` |\n| started_at | timestamptz | |\n| answered_at | timestamptz | |\n| ended_at | timestamptz | |\n| duration_seconds | integer | |\n| recording_url | text | |\n| full_transcript | text | Complete call transcript |\n| transferred_to | uuid | Agent ID if warm-transferred |\n| transfer_summary | text | AI-generated summary for agent |\n| disposition | text | `resolved` / `escalated` / `voicemail` / `abandoned` / `callback_requested` |\n\nIndexes: `conversation_id`, `merchant_id`, `(phone_from, merchant_id)`.\n\n### `cs_merchant_config` (altered)\n\n| Column | Type | Notes |\n|---|---|---|\n| voice_config | jsonb | ElevenLabs agent ID, voice ID, greeting mode, language, phone numbers |\n\n### Credentials\n\nElevenLabs API key is a **platform-level secret** (Supabase edge function secret `ELEVENLABS_API_KEY`), not per-merchant. Per-merchant config (agent ID, phone numbers) is in `voice_config` above.\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Voice.md#L23 Tables", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-voice", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f4bda181cdb6a297e9c7d9b47d5bbd61e7d828dc15baa96f3a483ce21200351a", "truncated": false}, "is_active": true}, {"id": "fe20c78d-df30-5904-9872-6e43197d8cad", "feature_slug": "cs-voice", "title": "Functions", "content": "| Function | Type | Purpose |\n|---|---|---|\n| `cs_fn_create_voice_call` | Backend | Insert cs_voice_calls record, link to conversation |\n| `cs_fn_update_voice_call` | Backend | Update call status, duration, recording URL, transcript, disposition |\n| `cs_bff_get_voice_calls` | BFF | List voice calls for admin panel (filter by status, date, phone, agent) |\n| `cs_bff_get_voice_call_details` | BFF | Single call: metadata + transcript + recording + conversation messages |\n| `cs_bff_upsert_voice_config` | BFF | Admin saves voice settings to cs_merchant_config.voice_config |\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Voice.md#L63 Functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-voice", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ec48f6c8c822930f4f79d65e61293f010b5ba39840649bb7672750f8967e4b8e", "truncated": false}, "is_active": true}, {"id": "3af11df1-2878-580e-8ba9-b5cf38e042e7", "feature_slug": "cs-voice", "title": "Edge Functions", "content": "| Function | Purpose |\n|---|---|\n| `voice-custom-llm` | ElevenLabs Custom LLM endpoint. Receives OpenAI Chat Completions format, maps session → conversation, calls graph executor on Render, streams response. |\n| `webhook-elevenlabs` | Call lifecycle: `call.started` (resolve contact by phone, create conversation + voice call, map session), `call.ended` (save transcript/recording/duration, emit post-call Inngest event). |\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Voice.md#L75 Edge Functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-voice", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "cacc4236115e72c78d79de8afb6ed266c6faa0a683e2a50e1c31eee7cc4a6175", "truncated": false}, "is_active": true}, {"id": "72d27ba3-1009-532c-a5ed-f4af42ebf79c", "feature_slug": "cs-voice", "title": "Inngest Functions", "content": "| Function | Event | Purpose |\n|---|---|---|\n| `cs/voice.post-call` | `cs/voice.call_ended` | Post-call processing: save full transcript, extract memory (same agent as chat), trigger CSAT via SMS/LINE, log analytics |\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Voice.md#L84 Inngest Functions", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-voice", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "fc8b20081639262ae952b8d02f566e1d81119026eb7bed278890b88c4488684a", "truncated": false}, "is_active": true}, {"id": "4b403116-f8a9-546e-93e1-3a6dafc89e1b", "feature_slug": "cs-voice", "title": "CS Voice Domain Reference", "content": "**Keywords:** voice, phone, call, inbound, outbound, stt, tts, speech_to_text, text_to_speech, elevenlabs, scribe, twilio, sip, telephony, recording, transcript, ivr, voice_call, cs_voice_calls, voice_config, graph_executor, deterministic_prefetch, custom_llm, vad, barge_in, warm_transfer\n**Source:** `CS_Voice.md`\n**Tables:** `cs_voice_calls`, `cs_merchant_config` (voice_config column). ElevenLabs API key is a platform-level Supabase secret, NOT in `merchant_credentials`.\n| Function | Type | Purpose |\n|---|---|---|\n| `cs_fn_create_voice_call` | Backend | Insert voice call record, link to conversation |\n| `cs_fn_update_voice_call` | Backend | Update call status, duration, recording, transcript |\n| `cs_bff_get_voice_calls` | BFF | Admin: list voice calls with filters |\n| `cs_bff_get_voice_call_details` | BFF | Admin: call detail + transcript + recording |\n| `cs_bff_upsert_voice_config` | BFF | Admin: save voice settings |\n| `voice-custom-llm` | Edge | ElevenLabs Custom LLM endpoint. Graph executor prefetch + single LLM call. |\n| `webhook-elevenlabs` | Edge | Call lifecycle webhooks (call.started, call.ended) |\n| `cs/voice.post-call` | Inngest | Post-call: transcript, memory extraction, CSAT, analytics |\n**Key Business Rules (summary):**\n- ElevenLabs Custom LLM mode: STT/TTS/VAD/turn-taking/barge-in on ElevenLabs, all AI decisioning on cs-ai-service (Render)\n- ElevenLabs API key is platform-level (Supabase secret), agent ID + phone numbers are per-merchant (cs_merchant_config.voice_config)\n- Graph executor pattern: deterministic prefetch based on AOP step, single LLM call per turn (Haiku 4.5 for voice latency)\n- Same AOPs, same MCP tools, same knowledge base as chat — different orchestration (graph executor vs AgentKit)\n- Voice conversations use `cs_conversations.modality = ''voice''`, telephony metadata in `cs_voice_calls` (1:1)\n- Contact resolved by phone number via `cs_fn_resolve_contact(platform_type=''voice'')`\n- Post-call processing via Inngest (memory extraction, analytics) — same as chat post-resolution\n- Prefetch works ~80% of turns; LLM falls back to explorer mode (tool-call loop) for unpredictable data needs", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-voice.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-voice", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "9194be0c4f9da29cf24d32825eb25c312eacc4e4634bb96cf6c829298cf00af2", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

